#!/usr/bin/env bash
# Mutation proof for the honey-voice lane's Flying Fox unit and installer (generated by agents-bots-honey.org): each sabotaged copy MUST fail
# test_honey_voice_lane.py by a NAMED failure. Exit 0 = every mutant killed, 1 = a survivor or an error.
set -uo pipefail
HERE="$(CDPATH= cd -- "$(dirname -- "$0")" && pwd -P)"
LANE="$(dirname "$HERE")"
TMP="$(mktemp -d)"; trap 'rm -rf "$TMP"' EXIT
fail=0; killed=0
mutate() { # name file(relative to the lane) sed-expression
  local name="$1" file="$2" expr="$3" d="$TMP/$1" out rc names
  mkdir -p "$d/tests"; cp -r "$LANE/openrc" "$LANE"/*.template "$d"/; cp "$HERE/test_honey_voice_lane.py" "$d/tests/"
  sed -i "$expr" "$d/$file"
  if cmp -s "$LANE/$file" "$d/$file"; then echo "MUTATION NOT APPLIED: $name"; fail=1; return; fi
  out="$(timeout 300 python3 "$d/tests/test_honey_voice_lane.py" 2>&1)"; rc=$?
  if [ "$rc" = 124 ] || ! printf '%s\n' "$out" | grep -qE '^(FAILED \(|OK)'; then echo "INFRASTRUCTURE ERROR (not a kill): $name"; printf '%s\n' "$out" | tail -4 | sed 's/^/    | /'; fail=1; return; fi
  names="$(printf '%s\n' "$out" | grep -E '^(FAIL|ERROR):' | sed 's/^[A-Z]*: //; s/ (.*//' | head -3 | tr '\n' ' ')"
  if [ -n "$names" ]; then killed=$((killed+1)); echo "killed: $name by: $names"; else echo "SURVIVED (tests too weak): $name"; fail=1; fi
}
F=openrc/honey-voice-fox I=openrc/honey-voice-install
mutate fox-home-not-required      $F "/honey_voice_fox_home:?/d"
mutate fox-read-as-not-required   $F "/honey_voice_fox_read_as:?/d"
mutate fox-user-not-required      $F "/honey_voice_user:?/d"
mutate fox-engine-not-required    $F "/honey_voice_engine_root:?/d"
mutate fox-home-hardcoded         $F "s|^export HONEY_FOX_HOME=.*|export HONEY_FOX_HOME=/home/agent|"
mutate fox-user-hardcoded         $F "s|^command_user=.*|command_user=\"nobody:nobody\"|"
mutate fox-group-default-removed  $F "s|^: \"\${honey_voice_group:=.*|honey_voice_group=nogroup|"
mutate fox-no-stop                $F "s|^stop() {|stop_x() {|"
mutate fox-log-mode-loosened      $F "s|checkpath -f -m 0640|checkpath -f -m 0666|"
mutate fox-depend-wrong-order     $F "s|after net honey-codex|after net|"
mutate fox-path-not-extended      $F "s|^export PATH=.*|export PATH=\"\${PATH}\"|"
mutate fox-pidfile-renamed        $F "s|^pidfile=.*|pidfile=\"/run/fox.pid\"|"
mutate installer-skips-conf-check $I "s|^\[ \"\$VERB\" = install \] \&\& \[ \"\$noconf\" -eq 1 \] \&\& .*|true|"
mutate installer-ignores-fox-conf $I "s|for svc in honey-voice-badger honey-voice-fox; do|for svc in honey-voice-badger; do|" 
mutate installer-drops-fox-target $I "/^    \"\$SRC_FOX|/d"
mutate installer-no-backup        $I "s|^    \[ -e \"\$dst\" \] \&\& cp -p -- \"\$dst\" \"\$dst.bak-\$ts\"|    true|"
mutate installer-mode-777         $I "s/-m 0755/-m 0777/g"
mutate installer-root-not-needed  $I "s/ || \[ -n \"\${HONEY_VOICE_INITD_DIR:-}\" \] || { echo 'install requires root' >&2; exit 1; }/ || true/"
mutate installer-check-exits-0    $I "/^\[ \"\$noconf\" -eq 0 \]\$/d"
mutate installer-starts-service   $I "s|^    echo \"installed \$dst\"|    echo \"installed \$dst\"; rc-service honey-voice-fox start|"
echo "mutants: $killed killed"
[ "$fail" = 0 ] || exit 1
exit 0
